// Recorded voice lines. Every spoken line in the game data is pre-generated by tools/voice into
// public/vo/<hash>.mp3, where hash is FNV-1a over the UTF-16 code units of "speaker|text". The index
// also holds each line's loudness envelope (20 samples a second, digits 0-9) so mouths follow the voice.

export function lineHash(who: string, text: string): string {
  const s = `${who}|${cleanLine(text)}`;
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, "0");
}
export const cleanLine = (t: string): string => t.replace(/[“”"]/g, "").replace(/\s+/g, " ").trim();

export class Voices {
  private index: Record<string, string> = {};
  private current: { audio: HTMLAudioElement; env: string } | null = null;
  muted = false;
  /** 0..1 from the settings; 0 means no recorded voices at all. */
  volume = 1;

  async load(base = "vo/"): Promise<void> {
    try { const r = await fetch(base + "index.json"); if (r.ok) this.index = await r.json(); } catch { /* voices are optional */ }
    this.base = base;
  }
  private base = "vo/";

  has(who: string, text: string): boolean { return lineHash(who, text) in this.index; }

  /** Starts a line. Returns true if a recording exists for it. */
  play(who: string, text: string): boolean {
    this.stop();
    const h = lineHash(who, text), env = this.index[h];
    if (env === undefined || this.muted || this.volume <= 0) return false;
    const audio = new Audio(this.base + h + ".mp3"); audio.volume = this.volume;
    audio.play().catch(() => { /* blocked until the player interacts; the line still shows */ });
    this.current = { audio, env };
    return true;
  }

  stop(): void { if (this.current) { this.current.audio.pause(); this.current = null; } }

  get playing(): boolean { return !!this.current && !this.current.audio.ended && !this.current.audio.paused; }

  /** 0..1 loudness of the playing line right now, for the speaker's mouth. */
  level(): number {
    const c = this.current; if (!c || c.audio.ended || c.audio.paused) return 0;
    const i = Math.floor(c.audio.currentTime * 20), ch = c.env[i];
    return ch === undefined ? 0 : Number(ch) / 9;
  }
}
